/**
 * Guides Catalog — Programmatic SEO for commercial-intent Hebrew long-tail queries.
 *
 * Each entry targets ONE primary keyword with supporting secondaries. The renderer
 * at [app/sites/main/guides/[slug]/page.tsx] composes these into full pages with
 * Article + FAQPage + HowTo + BreadcrumbList JSON-LD, a Speakable definition box,
 * and a CTA to the relevant WeCcelerate service.
 *
 * Strategy:
 * - Pick keywords where competitors are weak and commercial intent is high.
 * - Exact-match H1 that contains the primary keyword.
 * - 30–60 word Speakable answer box (what Google AI + Alexa read aloud).
 * - 800–1500 words of unique Hebrew body content, headings mirror search intent.
 * - 4–8 FAQ entries on the long-tail query variations.
 * - Internal links to 3–5 related guides and 1 service page.
 *
 * To add a new guide: append an entry below. That's it — routes, sitemap,
 * and hub listing update automatically.
 */

export type GuideCategory =
 | 'startup-basics'
 | 'product-development'
 | 'medtech'
 | 'fundraising'
 | 'regulatory'
 | 'comparison';

export interface GuideSection {
 heading: string;
 paragraphs: string[];
 list?: string[];
}

export interface GuideHowToStep {
 name: string;
 text: string;
 url?: string;
}

export interface GuideFaq {
 q: string;
 a: string;
}

export interface Guide {
 slug: string;
 category: GuideCategory;
 /** Primary Hebrew keyword that the page targets for ranking. */
 targetKeyword: string;
 relatedKeywords: string[];
 /** H1 — must include the targetKeyword verbatim. */
 h1: string;
 /** 55–65 chars. Includes keyword + brand. */
 metaTitle: string;
 /** 150–160 chars. Compelling summary. */
 metaDescription: string;
 /** 30–60 words — rendered with data-speakable. This is what Google AI / ChatGPT cite. */
 speakableAnswer: string;
 /** When the guide was last rewritten (used in schema dateModified). */
 lastUpdated: string;
 readingTimeMinutes: number;
 sections: GuideSection[];
 /** When present, HowTo schema is emitted in addition to Article. */
 howToSteps?: GuideHowToStep[];
 faqs: GuideFaq[];
 relatedGuideSlugs: string[];
 /** Service to CTA at the bottom. Path under /services/. */
 ctaServicePath: string;
 ctaLabel: string;
}

