 '**Bad Leaver**: מייסד שעוזב בנסיבות פסולות (הפרת הסכם, התחרות עם החברה, מעילה באמון, הפרת סעיפי סודיות). מאבד את כל ה-Vesting, גם את החלקים שכבר התגבשו.',
 'ההגדרה המדויקת של Bad Leaver חייבת להיות בהסכם. חסימה של תקופה תלוית-היקף התחרות + תקופה תלוית-היקף איסור Solicitation של עובדים/לקוחות היא סטנדרט בישראל. זה סעיף שמנהלת קרן סבירה תסתכל עליו ב-Due Diligence.',
