 'Delaware Flip הוא תהליך משפטי שבו סטארטאפ ישראלי — חברה בע"מ הרשומה ברשם החברות בישראל — הופכת לחברת-בת של חברת-אם חדשה ב-Delaware, ארה"ב (Delaware C-Corp). כל המניות של החברה הישראלית מוחלפות במניות של החברה האמריקאית. המייסדים והמשקיעים הקיימים מקבלים מניות בחברה האמריקאית.',
