 'NDA כשלעצמו לא מגן על הרעיון — רעיונות לא מוגנים על ידי דיני יוצרים או פטנט. הוא מגן על המידע הספציפי שעובר. אם תוכל להוכיח שהצד השני גילה מידע סודי לצד שלישי — יש לך זכות תביעה.',
